namespace AmznSellingPartner.Clients.AplusContent.AplusContent20201101
{
    using Newtonsoft.Json;
    using Newtonsoft.Json.Converters;

    using System.Runtime.Serialization;

    /// <summary>
    /// A flag that provides additional information about an A+ Content document.
    /// </summary>
    [JsonConverter(typeof(StringEnumConverter))]
    public enum ContentBadge
    {
        /// <summary>
        /// This content is applied to ASINs in bulk.
        /// </summary>
        [EnumMember(Value = "BULK")]
        BULK,

        /// <summary>
        /// This content is generated by an automated process. If any user modifies this content, it will
        /// lose the GENERATED badge.
        /// </summary>
        [EnumMember(Value = "GENERATED")]
        GENERATED,

        /// <summary>
        /// Launchpad content.
        /// </summary>
        [EnumMember(Value = "LAUNCHPAD")]
        LAUNCHPAD,

        /// <summary>
        /// Premium content
        /// </summary>
        [EnumMember(Value = "PREMIUM")]
        PREMIUM,

        /// <summary>
        /// Standard content.
        /// </summary>
        [EnumMember(Value = "STANDARD")]
        STANDARD,
    }
}
